/// <summary>
/// Returns a formatted string representation of this data size.
/// </summary>
/// <param name="format">A standard or custom numeric format string.</param>
/// <param name="provider">An object that supplies culture-specific formatting information.</param>
/// <returns>A formatted string representing this data size.</returns>
public string ToString(string? format, IFormatProvider? formatProvider = null)
{
    format ??= "0.## ";
    formatProvider ??= CultureInfo.CurrentCulture;

    if (!format.Contains('#') && !format.Contains('0'))
    {
        format = "0.## " + format;
    }

    format = format.Replace("#.##", "0.##");

    // Try to match a unit symbol in the format string and split it out,
    // avoiding repeated Replace/Contains calls per invocation.
    if (TrySplitUnit(format, TerabyteSymbol, out var numericFormat))
        return Terabytes.ToString(numericFormat, formatProvider) + TerabyteSymbol;

    if (TrySplitUnit(format, GigabyteSymbol, out numericFormat))
        return Gigabytes.ToString(numericFormat, formatProvider) + GigabyteSymbol;

    if (TrySplitUnit(format, MegabyteSymbol, out numericFormat))
        return Megabytes.ToString(numericFormat, formatProvider) + MegabyteSymbol;

    if (TrySplitUnit(format, KilobyteSymbol, out numericFormat))
        return Kilobytes.ToString(numericFormat, formatProvider) + KilobyteSymbol;

    if (TrySplitUnit(format, ByteSymbol, out numericFormat))
        return Bytes.ToString(numericFormat, formatProvider) + ByteSymbol;

    if (TrySplitUnit(format, BitSymbol, out numericFormat))
        return ((double)_bits).ToString(numericFormat, formatProvider) + BitSymbol;

    GetLargestWholeNumber(out var value, out var symbol);
    return value.ToString(format, formatProvider) + " " + symbol;
}

/// <summary>
/// Finds <paramref name="unit"/> in <paramref name="format"/> (case-insensitive ordinal)
/// and splits it into the numeric portion.
/// </summary>
private static bool TrySplitUnit(string format, string unit, out string numericFormat)
{
    var idx = format.IndexOf(unit, StringComparison.OrdinalIgnoreCase);
    if (idx >= 0)
    {
        // Remove the unit token, keeping the numeric format intact.
        numericFormat = string.Concat(format.AsSpan(0, idx), format.AsSpan(idx + unit.Length));
        return true;
    }
    numericFormat = format;
    return false;
}

